schema:
CREATE TABLE table2 (
    c131 INT,
    c68 INT,
    c145 VARCHAR,
    PRIMARY KEY (c131),
    FOREIGN KEY (c68) REFERENCES table1(c131)
);

CREATE TABLE table1 (
    c131 INT,
    c145 VARCHAR,
    PRIMARY KEY (c131)
);

counterexample:
INSERT INTO table1 (c131, c145) VALUES (1, 'Netherlands');
INSERT INTO table1 (c131, c145) VALUES (2, 'Netherlands');
